        bodyScroll, windowHeight, windowHeight2;
	var currentPageUrl = window.location.pathname;

    function sectionAni() {
        bodyScroll = $(document).scrollTop(),
            windowHeight = $(window).height() / 1.15;
            windowHeight2 = $(window).height() / 3;

        $section.each(function() {
            if (bodyScroll >= $(this).offset().top + 80 - windowHeight && bodyScroll < $(this).offset().top + $(this).height()) {
                $(this).addClass('on');
                $(this).addClass('subOn');
				$('.listbox').each(function() {
					var ul = $(this).find('> ul');
					if ($(this).hasClass('subOn')) {
						$(this).addClass('subOn');
						if (currentPageUrl.indexOf("group.php") !== -1 || currentPageUrl.indexOf("recruitment.php") !== -1 || currentPageUrl.indexOf("sustainability.php") !== -1) {
							setTimeout(function() {
								ul.addClass('active');
							}, 300);
						} else {
							setTimeout(function() {
								ul.addClass('active');
							}, 1300);
						}
					}
				});
            } else {
                $(this).removeClass('on');
            }
        });

        $section_s.each(function() {
            if (bodyScroll >= $(this).offset().top - 80 - windowHeight2 && bodyScroll < $(this).offset().top + $(this).height()) {
                $(this).addClass('ov');
            } else {
                $(this).removeClass('ov');
            }
        });
    }
    $(function() {
        sectionAni();
    });
